import{_ as d,o as e,c as a,ag as r}from"./chunks/framework.BcZEdlUI.js";const p=JSON.parse('{"title":"AI 模型","description":"SceneFab 在视频理解、解说生成、语音识别和配音合成中的模型选择与配置。","frontmatter":{"title":"AI 模型","description":"SceneFab 在视频理解、解说生成、语音识别和配音合成中的模型选择与配置。"},"headers":[],"relativePath":"ai-models.md","filePath":"ai-models.md","lastUpdated":1781581339000}'),h={name:"ai-models.md"};function o(l,t,i,n,s,b){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="ai-模型" tabindex="-1">AI 模型 <a class="header-anchor" href="#ai-模型" aria-label="Permalink to &quot;AI 模型&quot;">​</a></h1><p>SceneFab 的模型层服务于第一人称影视/短剧解说生产。当前策略是只保留最新、质量优先的模型栈：中文剧情理解优先，长上下文可用。所有模型名称、参数和能力声明由 <code>services.ai.model_catalog</code> 统一管理，配置文件和 Provider 不得各自硬编码。</p><h2 id="模型总览" tabindex="-1">模型总览 <a class="header-anchor" href="#模型总览" aria-label="Permalink to &quot;模型总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>模型</th><th>上下文长度</th><th>最大输出</th><th>视觉能力</th><th>开源</th></tr></thead><tbody><tr><td>Qwen</td><td>qwen3.7-max</td><td>1,000K</td><td>32,768</td><td>是</td><td>否</td></tr><tr><td>Qwen</td><td>qwen3.7-plus</td><td>1,000K</td><td>16,384</td><td>是</td><td>否</td></tr><tr><td>DeepSeek</td><td>deepseek-v4-pro</td><td>1,000K</td><td>32,768</td><td>否</td><td>否</td></tr><tr><td>DeepSeek</td><td>deepseek-v4-flash</td><td>1,000K</td><td>16,384</td><td>否</td><td>否</td></tr><tr><td>OpenAI</td><td>gpt-5</td><td>1,000K</td><td>32,768</td><td>是</td><td>否</td></tr><tr><td>OpenAI</td><td>gpt-5-mini</td><td>1,000K</td><td>16,384</td><td>是</td><td>否</td></tr><tr><td>Claude</td><td>claude-opus-4-6</td><td>200K</td><td>16,384</td><td>是</td><td>否</td></tr><tr><td>Claude</td><td>claude-sonnet-4-5</td><td>200K</td><td>16,384</td><td>是</td><td>否</td></tr><tr><td>Gemini</td><td>gemini-3.1-pro</td><td>2,000K</td><td>8,192</td><td>是</td><td>否</td></tr><tr><td>Gemini</td><td>gemini-3.1-flash</td><td>1,000K</td><td>8,192</td><td>是</td><td>否</td></tr><tr><td>Kimi</td><td>moonshot-v1-128k</td><td>128K</td><td>8,000</td><td>否</td><td>否</td></tr><tr><td>GLM</td><td>glm-5-plus</td><td>128K</td><td>16,384</td><td>否</td><td>否</td></tr><tr><td>GLM</td><td>glm-5-flash</td><td>128K</td><td>8,192</td><td>否</td><td>否</td></tr><tr><td>Doubao</td><td>doubao-pro-128k</td><td>128K</td><td>64,000</td><td>否</td><td>否</td></tr><tr><td>Hunyuan</td><td>hunyuan-pro</td><td>128K</td><td>8,000</td><td>否</td><td>否</td></tr><tr><td>本地</td><td>qwen3:32b</td><td>128K</td><td>8,192</td><td>否</td><td>是</td></tr><tr><td>本地</td><td>deepseek-r1:32b</td><td>128K</td><td>8,192</td><td>否</td><td>是</td></tr></tbody></table><h2 id="模型分层" tabindex="-1">模型分层 <a class="header-anchor" href="#模型分层" aria-label="Permalink to &quot;模型分层&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>主要职责</th><th>默认模型</th><th>备选模型</th></tr></thead><tbody><tr><td>视频理解</td><td>分析画面、人物、动作、场景和冲突</td><td>Qwen3.7 Max</td><td>Gemini 3.1 Pro / Qwen3.7 Plus</td></tr><tr><td>解说生成</td><td>生成第一人称脚本、Hook、桥段和结尾钩子</td><td>DeepSeek V4 Pro</td><td>Qwen3.7 Max / GPT-5</td></tr><tr><td>质量评估</td><td>一致性校验、桥段回灌、结构审稿</td><td>Qwen3.7 Max</td><td>Claude Opus 4.6</td></tr><tr><td>语音识别</td><td>提取原片对白和声音线索</td><td>SenseVoice</td><td>Whisper</td></tr><tr><td>配音合成</td><td>生成解说音频和时间戳</td><td>Edge-TTS</td><td>F5-TTS</td></tr></tbody></table><h2 id="推荐配置" tabindex="-1">推荐配置 <a class="header-anchor" href="#推荐配置" aria-label="Permalink to &quot;推荐配置&quot;">​</a></h2><p>根据生产角色选择最优模型组合：</p><h3 id="视频理解" tabindex="-1">视频理解 <a class="header-anchor" href="#视频理解" aria-label="Permalink to &quot;视频理解&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>推荐模型</th><th>说明</th></tr></thead><tbody><tr><td>中文短剧/影视片段</td><td>qwen3.7-max</td><td>默认主力，中文语境和桥段识别最佳</td></tr><tr><td>长片/复杂剧情校验</td><td>gemini-3.1-pro</td><td>2M 上下文，适合长视频多模态交叉复核</td></tr><tr><td>批量短剧分析</td><td>qwen3.7-plus</td><td>高吞吐，适合批量素材预处理</td></tr><tr><td>隐私敏感素材</td><td>qwen3:32b (本地)</td><td>开源本地部署，素材不上传</td></tr></tbody></table><h3 id="解说生成" tabindex="-1">解说生成 <a class="header-anchor" href="#解说生成" aria-label="Permalink to &quot;解说生成&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>推荐模型</th><th>说明</th></tr></thead><tbody><tr><td>第一人称解说/短剧脚本</td><td>deepseek-v4-pro</td><td>默认主力，中文叙事能力强</td></tr><tr><td>Hook 快速迭代</td><td>deepseek-v4-flash</td><td>低延迟，适合批量草稿和改写</td></tr><tr><td>剧情一致性评估</td><td>qwen3.7-max</td><td>与视频理解共享语义上下文</td></tr><tr><td>高价值成片质检</td><td>claude-opus-4-6 / gpt-5</td><td>跨模型复核，长结构审稿</td></tr></tbody></table><h3 id="配音合成" tabindex="-1">配音合成 <a class="header-anchor" href="#配音合成" aria-label="Permalink to &quot;配音合成&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>推荐方案</th><th>说明</th></tr></thead><tbody><tr><td>快速出片</td><td>Edge-TTS</td><td>免费、低门槛、多音色</td></tr><tr><td>音色一致/人设声线</td><td>F5-TTS</td><td>支持音色克隆，声线更稳定</td></tr></tbody></table><h2 id="组合方案" tabindex="-1">组合方案 <a class="header-anchor" href="#组合方案" aria-label="Permalink to &quot;组合方案&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>视频理解</th><th>解说生成</th><th>配音</th><th>适用场景</th></tr></thead><tbody><tr><td>快速出片</td><td>qwen3.7-max</td><td>deepseek-v4-pro</td><td>Edge-TTS</td><td>日常生产，性价比最高</td></tr><tr><td>本地优先</td><td>qwen3:32b</td><td>deepseek-v4-pro</td><td>Edge-TTS</td><td>隐私敏感素材</td></tr><tr><td>音色一致</td><td>qwen3.7-max</td><td>deepseek-v4-pro</td><td>F5-TTS</td><td>需要统一人设声线</td></tr><tr><td>长片理解</td><td>gemini-3.1-pro</td><td>deepseek-v4-pro</td><td>Edge-TTS</td><td>电影/剧集长片</td></tr><tr><td>最高质量</td><td>qwen3.7-max</td><td>deepseek-v4-pro + claude-opus-4-6 复核</td><td>F5-TTS</td><td>高价值成片</td></tr></tbody></table><h2 id="本地模型" tabindex="-1">本地模型 <a class="header-anchor" href="#本地模型" aria-label="Permalink to &quot;本地模型&quot;">​</a></h2><p>SceneFab 支持通过 Ollama 或 LM Studio 运行本地模型，适用于隐私敏感场景：</p><table tabindex="0"><thead><tr><th>模型</th><th>参数量</th><th>用途</th><th>说明</th></tr></thead><tbody><tr><td>qwen3:32b</td><td>32B</td><td>视频理解/脚本初稿</td><td>推荐本地部署首选</td></tr><tr><td>deepseek-r1:32b</td><td>32B</td><td>推理/评估</td><td>开源推理模型</td></tr></tbody></table><p>本地模型需要在 <code>config/llm.yaml</code> 中配置 <code>local</code> 提供商的 <code>base_url</code>（默认 <code>http://localhost:11434</code>）。</p><h2 id="安全提示" tabindex="-1">安全提示 <a class="header-anchor" href="#安全提示" aria-label="Permalink to &quot;安全提示&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">重要</p><p>API Key 只应保存在系统 Keychain、加密配置或受控环境变量中。不要把密钥写入截图、公开文档、项目备注或共享素材包。</p></div><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/scene-fab/config.html">配置参考</a> — 两文件配置结构与 API Key 设置</li><li><a href="/scene-fab/architecture.html">架构概览</a> — ModelCatalog 单源真相机制</li></ul>',24)])])}const u=d(h,[["render",o]]);export{p as __pageData,u as default};
